// Build the dataset the head-to-head compare page needs.
//   node scripts/gen-compare-data.mjs
// Produces:
//   public/compare-data.json  one compact row per athlete with, for each
//   event x season they've competed: the monotonic best-mark progression,
//   the PB (mark / date / results link) and the all-time team-list ranks.
//
// Kept out of the JS bundle — /compare fetches this once on first visit and
// the service worker caches it. Regenerated by `npm run data` and as a
// prebuild / predev step so it never drifts from data/.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));

const athletes = read("data/athletes.json");
const performances = read("data/performances.json");
const events = read("data/events.json");
const topTen = read("data/top10.json");

const evHib = new Map(events.map((e) => [e.event_id, e.higher_is_better]));

// team rank: athlete's place on the official all-time list for event x
// gender x season (mirrors lib/data.ts teamRank)
const topIdx = new Map();
for (const list of topTen) {
  if (list.event_id != null && !list.relay) {
    topIdx.set(`${list.event_id}|${list.gender}|${list.season}`, list);
  }
}
const rankOf = (athleteId, eventId, season, gender) => {
  if (!gender) return null;
  const list = topIdx.get(`${eventId}|${gender}|${season}`);
  const e = list?.entries.find((x) => x.athlete_id === athleteId);
  return e ? e.rank : null;
};

// perfs grouped by athlete -> `${event_id}|${season}`
const byAthlete = new Map();
for (const p of performances) {
  let m = byAthlete.get(p.athlete_id);
  if (!m) byAthlete.set(p.athlete_id, (m = new Map()));
  const k = `${p.event_id}|${p.season}`;
  const arr = m.get(k);
  if (arr) arr.push(p);
  else m.set(k, [p]);
}

const isFormer = (a) => !a.active || a.status != null;

const out = [];
for (const a of athletes) {
  const groups = byAthlete.get(a.athlete_id);
  if (!groups) continue;

  const sex = a.sex ? a.sex.toLowerCase() : null;
  const evOut = [];

  for (const [key, perfs] of groups) {
    const [eventId, season] = key.split("|");
    const eid = Number(eventId);
    const hib = evHib.get(eid) ?? false;

    perfs.sort((x, y) => x.date.localeCompare(y.date));

    // monotonic best-to-date line (only the marks that improved)
    const prog = [];
    let best = hib ? -Infinity : Infinity;
    let pbRow = null;
    for (const p of perfs) {
      if (hib ? p.mark > best : p.mark < best) {
        best = p.mark;
        prog.push([p.date, p.mark]);
        pbRow = p;
      }
    }
    if (prog.length === 0) continue;

    // event name / higher-is-better are looked up client-side from a small
    // events map the page already has; the results link lives on the profile.
    evOut.push({
      e: eid,
      s: season, // "i" | "o"
      pb: pbRow.mark,
      d: pbRow.date,
      r: rankOf(a.athlete_id, eid, season === "i" ? "indoor" : "outdoor", sex),
      p: prog,
    });
  }

  if (evOut.length === 0) continue;
  evOut.sort((x, y) => x.e - y.e || x.s.localeCompare(y.s));

  const row = {
    id: a.athlete_id,
    n: `${a.nickname || a.first_name} ${a.last_name}`,
    x: sex,
    ev: evOut,
  };
  if (a.nickname && a.nickname.toLowerCase() !== a.first_name.toLowerCase()) {
    row.alt = `${a.first_name} ${a.last_name}`;
  }
  if (isFormer(a)) {
    row.f = 1;
    if (a.graduation_year) row.gy = a.graduation_year;
    if (a.status) row.st = a.status;
  }
  out.push(row);
}

out.sort((a, b) => a.n.localeCompare(b.n));

writeFileSync(
  join(root, "public", "compare-data.json"),
  JSON.stringify(out) + "\n"
);

const bytes = readFileSync(join(root, "public", "compare-data.json")).length;
console.log(
  `wrote public/compare-data.json (${out.length} athletes, ${(bytes / 1024).toFixed(0)} KB)`
);
